sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    /*
     * Only run when Response changes TO Accepted.
     */

    var acceptedValue =
        getChoiceValueByLabel(
            current.getTableName(),
            'response',
            'Accepted'
        );

    var pendingValue =
        getChoiceValueByLabel(
            current.getTableName(),
            'response',
            'Pending'
        );

    if (!acceptedValue) {
        return;
    }

    if (
        !current.response.changesTo(
            acceptedValue
        )
    ) {
        return;
    }


    /*
     * ============================================================
     * PARENT REQUEST
     * ============================================================
     */

    var requestId =
        String(
            current.getValue('request') || ''
        );

    if (!requestId) {
        return;
    }

    var request =
        new GlideRecord(
            'x_snc_campus360_mock_interview_slot_request'
        );

    if (!request.get(requestId)) {
        return;
    }


    /*
     * ============================================================
     * FIRST-TRAINER-WINS
     * ============================================================
     */

    var parentAcceptedValue =
        getChoiceValueByLabel(
            request.getTableName(),
            'status',
            'Accepted'
        );

    if (
        parentAcceptedValue &&
        String(
            request.getValue('status')
        ) === String(parentAcceptedValue)
    ) {

        /*
         * Another trainer has already accepted.
         *
         * Do not allow a second trainer to become accepted.
         */

        var alreadyAcceptedTrainer = '';

        if (
            request.isValidField('accepted_trainer')
        ) {

            alreadyAcceptedTrainer =
                String(
                    request.getValue(
                        'accepted_trainer'
                    ) || ''
                );
        }

        var currentTrainer = '';

        if (
            current.isValidField('trainer')
        ) {

            currentTrainer =
                String(
                    current.getValue('trainer') || ''
                );
        }

        if (
            alreadyAcceptedTrainer &&
            currentTrainer &&
            alreadyAcceptedTrainer !== currentTrainer
        ) {

            if (pendingValue) {

                current.setValue(
                    'response',
                    pendingValue
                );
            }

            return;
        }
    }


    /*
     * ============================================================
     * GET THE SELECTED AVAILABILITY
     * ============================================================
     */

    var availabilityId = '';

    if (
        request.isValidField('requested_timing') &&
        request.getValue('requested_timing')
    ) {

        availabilityId =
            String(
                request.getValue(
                    'requested_timing'
                )
            );
    }

    if (
        !availabilityId &&
        request.isValidField('selected_availability') &&
        request.getValue('selected_availability')
    ) {

        availabilityId =
            String(
                request.getValue(
                    'selected_availability'
                )
            );
    }

    if (!availabilityId) {
        return;
    }


    var availability =
        new GlideRecord(
            'x_snc_campus360_trainer_interview_availability'
        );

    if (!availability.get(availabilityId)) {

        if (pendingValue) {
            current.setValue(
                'response',
                pendingValue
            );
        }

        return;
    }


    /*
     * ============================================================
     * CHECK ACTIVE + AVAILABLE
     * ============================================================
     */

    var availableValue =
        getChoiceValueByLabel(
            availability.getTableName(),
            'status',
            'Available'
        );

    if (!availableValue) {

        if (pendingValue) {
            current.setValue(
                'response',
                pendingValue
            );
        }

        return;
    }

    var activeValue =
        String(
            availability.getValue('active')
        );

    var isActive =
        activeValue === '1' ||
        activeValue === 'true';

    var isAvailable =
        String(
            availability.getValue('status')
        ) === String(availableValue);


    /*
     * If the selected row is no longer available,
     * acceptance is rejected.
     */
    if (!isActive || !isAvailable) {

        if (pendingValue) {

            current.setValue(
                'response',
                pendingValue
            );
        }

        return;
    }


    /*
     * ============================================================
     * CHECK THE ENTIRE EXACT SLOT
     *
     * If another request already booked one of the trainers
     * for this exact date/time/type/skill, do not allow another
     * trainer acceptance.
     * ============================================================
     */

    var dateValue =
        String(
            availability.getValue(
                'available_date'
            ) || ''
        );

    var startValue =
        String(
            availability.getValue(
                'start_time'
            ) || ''
        );

    var endValue =
        String(
            availability.getValue(
                'end_time'
            ) || ''
        );

    var typeValue =
        String(
            availability.getValue(
                'interview_type'
            ) || ''
        );

    var skillValue = '';

    if (
        availability.isValidField(
            'skill_area'
        )
    ) {

        skillValue =
            String(
                availability.getValue(
                    'skill_area'
                ) || ''
            );
    }


    /*
     * Look for a Booked availability in this exact slot.
     */

    var bookedValue =
        getChoiceValueByLabel(
            availability.getTableName(),
            'status',
            'Booked'
        );

    if (bookedValue) {

        var booked =
            new GlideRecord(
                availability.getTableName()
            );

        booked.addQuery(
            'available_date',
            dateValue
        );

        booked.addQuery(
            'start_time',
            startValue
        );

        booked.addQuery(
            'end_time',
            endValue
        );

        booked.addQuery(
            'interview_type',
            typeValue
        );

        if (
            availability.isValidField(
                'skill_area'
            )
        ) {

            booked.addQuery(
                'skill_area',
                skillValue
            );
        }

        booked.addQuery(
            'status',
            bookedValue
        );

        booked.addQuery(
            'active',
            true
        );

        booked.setLimit(1);
        booked.query();

        if (booked.next()) {

            if (pendingValue) {

                current.setValue(
                    'response',
                    pendingValue
                );
            }

            return;
        }
    }


    /*
     * ============================================================
     * VALID ACCEPTANCE
     *
     * Set response_on here.
     * ============================================================
     */

    if (
        current.isValidField(
            'response_on'
        )
    ) {

        current.setValue(
            'response_on',
            new GlideDateTime().getValue()
        );
    }


    /*
     * ============================================================
     * LOCAL CHOICE HELPER
     * ============================================================
     */

    function getChoiceValueByLabel(
        tableName,
        fieldName,
        label
    ) {

        var choice =
            new GlideRecord('sys_choice');

        choice.addQuery(
            'name',
            tableName
        );

        choice.addQuery(
            'element',
            fieldName
        );

        choice.addQuery(
            'label',
            label
        );

        choice.addQuery(
            'inactive',
            false
        );

        choice.setLimit(1);
        choice.query();

        if (choice.next()) {

            return String(
                choice.getValue('value')
            );
        }

        return '';
    }

})(current, previous);
